// Tính ngày hôm qua theo múi giờ Asia/Ho_Chi_Minh
const vnNow = new Date(new Date().toLocaleString('en-US', { timeZone: 'Asia/Ho_Chi_Minh' }));
const yesterday = new Date(vnNow);
yesterday.setDate(vnNow.getDate() - 1);

const yyyy = yesterday.getFullYear();
const mm = String(yesterday.getMonth() + 1).padStart(2, '0');
const dd = String(yesterday.getDate()).padStart(2, '0');

return [{ json: { reportDate: `${yyyy}-${mm}-${dd}` } }];

const values = $('Đọc Google Sheet').first().json.values || [];

function isHeaderRow(row) {
  const first = String(row?.[0] ?? '').trim().toLowerCase();
  return first === 'ma_quang_cao' || first === 'mã quảng cáo';
}

function toNumber(value) {
  const raw = String(value ?? '').trim();
  if (!raw || raw === '#VALUE!' || raw === '#REF!') return 0;
  const normalized = raw.replace(/\./g, '').replace(',', '.');
  const n = Number(normalized);
  return Number.isFinite(n) ? n : 0;
}

if (values.length === 0) {
  return [{ json: { records: [], rowCount: 0, headers: [], headerMap: {} } }];
}

const headerRow = values[0];
const headerMap = {};
headerRow.forEach((h, i) => {
  const name = String(h).trim();
  if (name) headerMap[name] = i;  // bỏ header rỗng
});

// === Kiểm tra header bắt buộc (chia 2 nhóm theo DATA_SCHEMA_RULES) ===
const requiredBusinessHeaders = [
  "Ma_quang_cao", "Ngay", "Chi_tieu", "Mess_Comment",
  "Khach_hop_le", "SDT", "Khach_chot", "Doanh_thu"
];
const requiredRawHeaders = [
  "Luot_hien_thi", "Click_All"
];
const requiredHeaders = [...requiredBusinessHeaders, ...requiredRawHeaders];

for (const h of requiredHeaders) {
  if (headerMap[h] === undefined) {
    throw new Error(`Thiếu cột bắt buộc trong Sheet: ${h}`);
  }
}

// === Helper đọc an toàn theo tên cột ===
const col = (row, name) => {
  if (headerMap[name] === undefined) return '';
  return row?.[headerMap[name]] ?? '';
};
const colNum = (row, name) => {
  if (headerMap[name] === undefined) return 0;
  return toNumber(row[headerMap[name]]);
};

const dataRows = values.filter((row, index) =>
  !(index === 0 && isHeaderRow(row))
);

const records = dataRows.map((row) => ({
  // === Business Metrics ===
  ma_quang_cao:              col(row, 'Ma_quang_cao'),
  ngay:                      col(row, 'Ngay'),
  chien_dich:                col(row, 'Chien_dich'),
  ten_quang_cao:             col(row, 'Ten_quang_cao'),
  chi_tieu:                  colNum(row, 'Chi_tieu'),
  nguoi_tiep_can:            colNum(row, 'Nguoi_tiep_can'),
  ngan_sach:                 colNum(row, 'Ngan_sach'),
  click:                     colNum(row, 'click'),
  mess_comment:              colNum(row, 'Mess_Comment'),
  khach_sai_tep:             colNum(row, 'Khach_sai_tep'),
  khach_hop_le:              colNum(row, 'Khach_hop_le'),
  sdt:                       colNum(row, 'SDT'),
  khach_chot:                colNum(row, 'Khach_chot'),
  chi_phi_tren_khach_hop_le: colNum(row, 'Chi_phi_tren_khach_hop_le'),
  chi_phi_khach_tren_sdt:    colNum(row, 'Chi_phi_khach_tren_SDT'),
  doanh_thu:                 colNum(row, 'Doanh_thu'),
  ghi_chu:                   col(row, 'ghi_chu'),
  trang_thai:                col(row, 'Trang_Thai'),
  key:                       col(row, 'Key'),
  thoi_diem_cap_nhat:        col(row, 'Thoi_diem_cap_nhat'),
  // === Raw Metrics ===
  luot_hien_thi:  colNum(row, 'Luot_hien_thi'),
  tan_suat:       colNum(row, 'Tan_suat'),
  xem_3s:         colNum(row, 'Xem_3s'),
  video_25:       colNum(row, 'Video_25'),
  video_50:       colNum(row, 'Video_50'),
  video_75:       colNum(row, 'Video_75'),
  video_95:       colNum(row, 'Video_95'),
  thruplay:       colNum(row, 'ThruPlay'),
  click_ra_web:   colNum(row, 'Click_Ra_Web'),
  click_all:      colNum(row, 'Click_All'),
  // === Derived Metrics (debug only — không dùng tính KPI) ===
  ctr_link_sheet: colNum(row, 'CTR_Link'),
  ctr_all_sheet:  colNum(row, 'CTR_All'),
  cpm_sheet:      colNum(row, 'CPM'),
}));

return [{ json: {
  headers: headerRow,
  headerMap,
  records,
  rowCount: records.length
} }];

const records = $('Normalize Sheet Data').first().json.records || [];
const reportDate = $('Tính Ngày Hôm Qua').first().json.reportDate;

function normalizeDate(value) {
  const raw = String(value ?? '').trim();
  const dmy = raw.match(/^(\d{1,2})\/(\d{1,2})\/(\d{4})$/);
  if (dmy) {
    const [, d, m, y] = dmy;
    return `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  return raw;
}

const filtered = records.filter(r => normalizeDate(r.ngay) === reportDate);

if (filtered.length === 0) {
  return [{ json: {
    reportDate,
    hasData: false,
    filteredCount: 0,
    message: `📊 *BÁO CÁO META ADS — HÔM QUA*\n📅 Ngày: ${reportDate}\n⚠️ Không có dữ liệu trong Sheet cho ngày này.\n💡 Kiểm tra lại Meta Ads Daily Sheet Update.`
  }}];
}

// === Aggregate Raw Metrics ===
const totals = {
  spend:       0,
  luotHienThi: 0,
  click:       0,
  clickAll:    0,
  mess:        0,
  khachHopLe:  0,
  sdt:         0,
  khachChot:   0,
  doanhThu:    0,
};

for (const r of filtered) {
  totals.spend       += r.chi_tieu;
  totals.luotHienThi += r.luot_hien_thi;
  totals.click       += r.click;
  totals.clickAll    += r.click_all;
  totals.mess        += r.mess_comment;
  totals.khachHopLe  += r.khach_hop_le;
  totals.sdt         += r.sdt;
  totals.khachChot   += r.khach_chot;
  totals.doanhThu    += r.doanh_thu;
}

// === Tính KPI từ Raw Metrics ===
const kpis = {
  cpm:         totals.luotHienThi > 0
    ? Math.round(totals.spend / totals.luotHienThi * 1000) : null,
  ctrLink:     totals.luotHienThi > 0
    ? parseFloat((totals.click / totals.luotHienThi * 100).toFixed(2)) : null,
  ctrAll:      totals.luotHienThi > 0
    ? parseFloat((totals.clickAll / totals.luotHienThi * 100).toFixed(2)) : null,
  cpc:         totals.click > 0
    ? Math.round(totals.spend / totals.click) : null,
  costPerMess: totals.mess > 0
    ? Math.round(totals.spend / totals.mess) : null,
  cpl:         totals.khachHopLe > 0
    ? Math.round(totals.spend / totals.khachHopLe) : null,
  dtPerSDT:    totals.sdt > 0
    ? Math.round(totals.doanhThu / totals.sdt) : null,
};

// === Format Telegram ===
const fmt = (n) => Math.round(n).toLocaleString('vi-VN');
const fmtMoney = (n) => n === null ? 'N/A' : fmt(n) + 'đ';

const message = [
  `📊 *BÁO CÁO META ADS — HÔM QUA*`,
  `📅 Ngày: ${reportDate}`,
  ``,
  `💰 Chi tiêu: *${fmt(totals.spend)}đ*`,
  `📩 Mess: *${totals.mess}*`,
  `💵 Cost/Mess: *${fmtMoney(kpis.costPerMess)}*`,
  ``,
  `👤 Lead: *${totals.khachHopLe}*`,
  `💵 CPL: *${fmtMoney(kpis.cpl)}*`,
  ``,
  `📈 CPM: *${fmtMoney(kpis.cpm)}*`,
  `📈 CTR: *${kpis.ctrLink !== null ? kpis.ctrLink.toFixed(2) + '%' : 'N/A'}*`,
  `📈 CPC: *${fmtMoney(kpis.cpc)}*`,
  ``,
  `🏆 Khách chốt: *${totals.khachChot}*`,
  `💰 DT/SDT: *${fmtMoney(kpis.dtPerSDT)}*`,
].join('\n');

return [{ json: {
  reportDate,
  hasData: true,
  filteredCount: filtered.length,
  totals,
  kpis,
  message
} }];
